// Monta lista de databases a sincronizar com suas pastas destino
const dbs = [
  { id: $env.NOTION_JURIS_DATABASE_ID     || '6be2d8b624f54620acc0720498e22bbb', folder: '05-Jurisprudência' },
  { id: $env.NOTION_LEGISLACAO_DATABASE_ID || '12649f17d3fc42f8a54b5f68eb1afc42', folder: '02-Legislação' },
];
const since = $workflow.staticData.lastSyncAt || new Date(Date.now() - 24*3600*1000).toISOString();
return dbs.map(db => ({ json: { dbId: db.id, folder: db.folder, since } }));

// Injeta a pasta destino em cada página
const folder = $('Listar databases').item.json.folder;
return $input.all().map(item => ({ json: { ...item.json, _destFolder: folder } }));

// Converte blocos do Notion em Markdown com frontmatter
const pageData  = $('Injetar pasta destino').item.json;
const blocks    = $input.all().map(i => i.json);
const destFolder = pageData._destFolder || ($env.OBSIDIAN_VAULT_FOLDER || '01-Entrada');

function richText(rt = []) {
  return rt.map(t => {
    let s = t.plain_text || '';
    if (t.annotations?.code)          s = `\`${s}\``;
    if (t.annotations?.bold)          s = `**${s}**`;
    if (t.annotations?.italic)        s = `_${s}_`;
    if (t.annotations?.strikethrough) s = `~~${s}~~`;
    if (t.href)                       s = `[${s}](${t.href})`;
    return s;
  }).join('');
}

function blockMd(b, depth = 0) {
  const ind = '  '.repeat(depth);
  const t = b.type, d = b[t] || {};
  switch (t) {
    case 'heading_1':          return `# ${richText(d.rich_text)}`;
    case 'heading_2':          return `## ${richText(d.rich_text)}`;
    case 'heading_3':          return `### ${richText(d.rich_text)}`;
    case 'paragraph':          return richText(d.rich_text) || '';
    case 'bulleted_list_item': return `${ind}- ${richText(d.rich_text)}`;
    case 'numbered_list_item': return `${ind}1. ${richText(d.rich_text)}`;
    case 'to_do':              return `${ind}- [${d.checked ? 'x' : ' '}] ${richText(d.rich_text)}`;
    case 'quote':              return `> ${richText(d.rich_text)}`;
    case 'callout':            return `> [!NOTE]\n> ${richText(d.rich_text)}`;
    case 'toggle':             return `<details><summary>${richText(d.rich_text)}</summary>\n</details>`;
    case 'code':               return `\`\`\`${d.language || ''}\n${richText(d.rich_text)}\n\`\`\``;
    case 'divider':            return '---';
    case 'image': {
      const url = d.type === 'external' ? d.external?.url : d.file?.url;
      return url ? `![image](${url})` : '';
    }
    case 'bookmark': return `[${d.url}](${d.url})`;
    default:         return '';
  }
}

const props = pageData.properties || {};
function prop(key, fb = '') {
  const p = props[key];
  if (!p) return fb;
  switch (p.type) {
    case 'title':        return p.title?.[0]?.plain_text || fb;
    case 'rich_text':    return p.rich_text?.[0]?.plain_text || fb;
    case 'select':       return p.select?.name || fb;
    case 'multi_select': return (p.multi_select || []).map(s => s.name).join(', ');
    case 'date':         return p.date?.start || fb;
    case 'url':          return p.url || fb;
    default:             return fb;
  }
}

const title      = prop('Nome') || prop('Name') || prop('Título') || 'Sem título';
const tribunal   = prop('Tribunal') || prop('Órgão');
const numero     = prop('Número') || prop('numero');
const dataJulg   = prop('Data de julgamento') || prop('Data');
const status     = prop('Status');
const stableId   = prop('stable_id');
const notionUrl  = `https://notion.so/${pageData.id.replace(/-/g, '')}`;

const frontmatter = [
  '---',
  `notion_id: "${pageData.id}"`,
  `notion_url: "${notionUrl}"`,
  stableId   ? `stable_id: "${stableId}"` : '',
  tribunal   ? `tribunal: "${tribunal}"` : '',
  numero     ? `numero: "${numero}"` : '',
  dataJulg   ? `data_julgamento: ${dataJulg}` : '',
  status     ? `status: ${status}` : '',
  `last_synced: "${new Date().toISOString()}"`,
  `last_edited: "${pageData.last_edited_time}"`,
  '---',
].filter(Boolean).join('\n');

const body = blocks.map(b => blockMd(b)).filter(Boolean).join('\n\n');
const markdown = `${frontmatter}\n\n# ${title}\n\n${body}`;

const safeTitle  = title.replace(/[\/\\?%*:|"<>]/g, '-').trim();
const filePath   = `${destFolder}/${safeTitle}.md`;

return [{ json: { pageId: pageData.id, title, filePath, markdown, lastEdited: pageData.last_edited_time } }];

// Nota gravada com sucesso — atualiza timestamp global
$workflow.staticData.lastSyncAt = new Date().toISOString();
console.log(`[notion→obsidian] OK: ${$json.filePath}`);
return $input.all();

